struct LiveOrderService: OrderService {
    let db: Database
    func place(_ req: OrderRequest) async throws -> Order {
        try await db.transaction { tx in          // rollback when the closure throws
            let order = try await Order.create(req, on: tx)
            try await Stock.reserve(order, on: tx)
            return order
        }
    }
}
